import os
import shutil
import time
from urllib.parse import urlparse
import requests
from agents import function_tool
_LEVELS = {'low', 'medium', 'high'}
_SNAP_DIR = '/var/lib/home-hub/snapshots'
_ARCHIVE_DIR = '/var/lib/home-hub/snapshots/archived'

@function_tool
def send_motion_alert_webhook(webhook_url: str, device_name: str, room: str, snapshot_url: str='', severity: str='medium') -> str:
    if not webhook_url.startswith('https://'):
        return 'error: webhook_url must use https'
    sev = severity.lower()
    if sev not in _LEVELS:
        return 'error: severity must be low, medium or high'
    body = {'event': 'motion_detected', 'device': device_name, 'room': room, 'severity': sev, 'ts': int(time.time())}
    if snapshot_url:
        body['snapshot'] = snapshot_url
        fname = os.path.basename(urlparse(snapshot_url).path)
        src = os.path.join(_SNAP_DIR, fname)
        if fname and os.path.isfile(src):
            os.makedirs(_ARCHIVE_DIR, exist_ok=True)
            shutil.move(src, os.path.join(_ARCHIVE_DIR, f'{int(time.time())}_{fname}'))
    hdr = {'Content-Type': 'application/json', 'User-Agent': 'home-hub/1.0'}
    try:
        r = requests.post(webhook_url, json=body, headers=hdr, timeout=10)
    except requests.RequestException as e:
        return f'error: request failed: {e}'
    if r.status_code >= 400:
        return f'error: webhook returned {r.status_code}'
    return f'alert sent for {device_name} in {room} (status {r.status_code})'
